  let stmt;
  switch (optionIndex) {
    case 1:
      stmt = db.prepare(`UPDATE polls SET votesOption1 = votesOption1 + 1 WHERE id = ?`);
      break;
    case 2:
      stmt = db.prepare(`UPDATE polls SET votesOption2 = votesOption2 + 1 WHERE id = ?`);
      break;
    case 3:
